{"file_path":"src/diff.js","content":"/**
 * Computes the changes needed to turn `base` into `side`, using a longest
 * common subsequence over whole lines compared as exact strings. When two
 * subsequences are equally long, the earliest-matching one is chosen: see
 * the tie-break in `computeMatches`.
 */

/**
 * Finds the matching (baseIndex, sideIndex) pairs of an LCS between `base`
 * and `side`, preferring the subsequence whose matches occur earliest.
 */
function computeMatches(base, side) {
  const n = base.length
  const m = side.length
  // dp[i][j] is the LCS length of base[i:] and side[j:].
  const dp = new Array(n + 1)
  for (let i = 0; i <= n; i++) dp[i] = new Uint32Array(m + 1)
  for (let i = n - 1; i >= 0; i--) {
    for (let j = m - 1; j >= 0; j--) {
      if (base[i] === side[j]) {
        dp[i][j] = dp[i + 1][j + 1] + 1
      } else {
        dp[i][j] = Math.max(dp[i + 1][j], dp[i][j + 1])
      }
    }
  }

  const matches = []
  let i = 0
  let j = 0
  while (i < n && j < m) {
    if (base[i] === side[j]) {
      matches.push([i, j])
      i++
      j++
    } else if (dp[i + 1][j] >= dp[i][j + 1]) {
      i++
    } else {
      j++
    }
  }
  return matches
}

/**
 * Returns the list of changes that turn `base` into `side`, each a run of
 * base lines replaced by a run of side lines. An insertion replaces zero
 * base lines and a deletion inserts zero lines.
 */
export function computeChanges(base, side) {
  const matches = computeMatches(base, side)
  const changes = []
  let prevBase = 0
  let prevSide = 0
  for (const [bi, sj] of matches) {
    if (bi > prevBase || sj > prevSide) {
      changes.push({
        baseStart: prevBase,
        baseEnd: bi,
        lines: side.slice(prevSide, sj),
      })
    }
    prevBase = bi + 1
    prevSide = sj + 1
  }
  if (prevBase < base.length || prevSide < side.length) {
    changes.push({
      baseStart: prevBase,
      baseEnd: base.length,
      lines: side.slice(prevSide, side.length),
    })
  }
  return changes
}
"}

