{"file_path":"src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js merge`, `node src/cli.js merge2` and
 * `node src/cli.js regions` each read three documents from standard input and
 * report the three-way merge of the second into the first and the third.
 */

import { readFileSync } from 'node:fs'
import { buildRegions } from './merge.js'

const MODES = new Set(['merge', 'merge2', 'regions'])

function fail(message) {
  process.stderr.write(`${message}\n`)
  process.exit(2)
}

function splitDocuments(input) {
  const lines = input.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  const parts = [[]]
  for (const line of lines) {
    if (line === '%%%') {
      parts.push([])
    } else {
      parts[parts.length - 1].push(line)
    }
  }
  return parts
}

function main() {
  const mode = process.argv[2]
  if (process.argv.length !== 3 || !MODES.has(mode)) {
    fail('error: usage: cli.js merge|merge2|regions')
  }

  const input = readFileSync(0, 'utf8')
  const parts = splitDocuments(input)
  if (parts.length !== 3) {
    fail('error: expected three parts separated by %%%')
  }
  const [mine, base, theirs] = parts

  const regions = buildRegions(mine, base, theirs)

  let conflict = false
  const out = []
  if (mode === 'regions') {
    for (const region of regions) {
      if (region.kind === 'conflict') {
        conflict = true
        out.push(`conflict mine=${region.mineLines.length} base=${region.baseLines.length} theirs=${region.theirsLines.length}`)
      } else {
        out.push(`${region.kind} ${region.lines.length}`)
      }
    }
  } else {
    for (const region of regions) {
      if (region.kind === 'conflict') {
        conflict = true
        out.push('<<<<<<< mine', ...region.mineLines)
        if (mode === 'merge') out.push('||||||| base', ...region.baseLines)
        out.push('=======', ...region.theirsLines, '>>>>>>> theirs')
      } else {
        out.push(...region.lines)
      }
